<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }

function kimpu_register_layout_controls( $customizer ) {
	$section = 'kimpu_design_layout'; $customizer->add_section( $section, array( 'title' => __( 'Site Layout', 'kimpu-multipurpose' ), 'panel' => 'kimpu_global_design', 'priority' => 40 ) );
	$customizer->add_setting( 'kimpu_design_layout_mode', array( 'default' => 'full', 'sanitize_callback' => function( $v ) { return kimpu_sanitize_design_choice( $v, array( 'full', 'boxed' ), 'full' ); }, 'transport' => 'refresh' ) ); $customizer->add_control( 'kimpu_design_layout_mode', array( 'label' => __( 'Global Layout', 'kimpu-multipurpose' ), 'section' => $section, 'type' => 'select', 'choices' => array( 'full' => __( 'Full Width', 'kimpu-multipurpose' ), 'boxed' => __( 'Boxed Content', 'kimpu-multipurpose' ) ) ) );
	$colors = array( 'kimpu_design_page_background' => array( '#ffffff', __( 'Page Background', 'kimpu-multipurpose' ) ) ); foreach ( $colors as $id => $data ) { kimpu_add_design_color( $customizer, $id, $data[0], $data[1], $section ); }
	$fields = array( 'container_width' => array( 1200, 960, 1600, __( 'Content Container (px)', 'kimpu-multipurpose' ) ), 'wide_container' => array( 1320, 1100, 1800, __( 'Wide Container (px)', 'kimpu-multipurpose' ) ), 'reading_width' => array( 760, 560, 960, __( 'Reading Width (px)', 'kimpu-multipurpose' ) ), 'sidebar_width' => array( 300, 220, 420, __( 'Sidebar Width (px)', 'kimpu-multipurpose' ) ), 'content_gap' => array( 48, 20, 100, __( 'Content Gap (px)', 'kimpu-multipurpose' ) ) );
	foreach ( $fields as $key => $data ) { $id = 'container_width' === $key ? 'kimpu_container_width' : 'kimpu_design_' . $key; $customizer->add_setting( $id, array( 'default' => $data[0], 'sanitize_callback' => function( $v ) use ( $data ) { return (int) kimpu_sanitize_design_number( $v, $data[1], $data[2] ); }, 'transport' => 'postMessage' ) ); $customizer->add_control( $id, array( 'label' => $data[3], 'section' => $section, 'type' => 'number', 'input_attrs' => array( 'min' => $data[1], 'max' => $data[2], 'step' => 1 ) ) ); }
	$choices = array( 'sidebar_position' => array( 'right' => __( 'Right', 'kimpu-multipurpose' ), 'left' => __( 'Left', 'kimpu-multipurpose' ), 'none' => __( 'No Sidebar', 'kimpu-multipurpose' ) ), 'section_alignment' => array( 'left' => __( 'Left', 'kimpu-multipurpose' ), 'center' => __( 'Center', 'kimpu-multipurpose' ) ) ); foreach ( $choices as $key => $items ) { $id = 'kimpu_design_' . $key; $customizer->add_setting( $id, array( 'default' => array_key_first( $items ), 'sanitize_callback' => function( $v ) use ( $items ) { return array_key_exists( $v, $items ) ? $v : array_key_first( $items ); }, 'transport' => 'refresh' ) ); $customizer->add_control( $id, array( 'label' => ucwords( str_replace( '_', ' ', $key ) ), 'section' => $section, 'type' => 'select', 'choices' => $items ) ); }
}
